import pandas as pd
import numpy as np
import json
import base64
from io import BytesIO
from collections import Counter

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# Clean price columns
def clean_price(x):
    if pd.isna(x):
        return np.nan
    x = str(x).replace('₹', '').replace(',', '').strip()
    try:
        return float(x)
    except:
        return np.nan

def clean_discount(x):
    if pd.isna(x):
        return np.nan
    x = str(x).replace('%', '').strip()
    try:
        return float(x)
    except:
        return np.nan

def clean_rating_count(x):
    if pd.isna(x):
        return np.nan
    x = str(x).replace(',', '').strip()
    try:
        return int(float(x))
    except:
        return np.nan

def clean_rating(x):
    if pd.isna(x):
        return np.nan
    try:
        return float(x)
    except:
        return np.nan

df['discounted_price_clean'] = df['discounted_price'].apply(clean_price)
df['actual_price_clean'] = df['actual_price'].apply(clean_price)
df['discount_percentage_clean'] = df['discount_percentage'].apply(clean_discount)
df['rating_clean'] = df['rating'].apply(clean_rating)
df['rating_count_clean'] = df['rating_count'].apply(clean_rating_count)

# Extract categories
def get_top_category(x):
    if pd.isna(x):
        return 'Unknown'
    parts = str(x).split('|')
    return parts[0].strip() if parts else 'Unknown'

df['top_category'] = df['category'].apply(get_top_category)

# Calculate correlations
valid_data = df.dropna(subset=['discount_percentage_clean', 'rating_clean'])
correlation_discount_rating = valid_data['discount_percentage_clean'].corr(valid_data['rating_clean'])

valid_data_rc = df.dropna(subset=['discount_percentage_clean', 'rating_count_clean'])
correlation_discount_count = valid_data_rc['discount_percentage_clean'].corr(valid_data_rc['rating_count_clean'])

# KPIs
total_products = len(df)
avg_rating = df['rating_clean'].mean()
median_discount = df['discount_percentage_clean'].median()
median_rating_count = df['rating_count_clean'].median()
high_rating_share = (df['rating_clean'] >= 4.0).sum() / total_products * 100

# Category stats
category_stats = df.groupby('top_category').agg({
    'product_id': 'count',
    'rating_clean': 'mean',
    'discount_percentage_clean': 'mean',
    'rating_count_clean': 'median'
}).rename(columns={
    'product_id': 'count',
    'rating_clean': 'avg_rating',
    'discount_percentage_clean': 'avg_discount',
    'rating_count_clean': 'median_rating_count'
}).sort_values('avg_rating', ascending=False)

# Rating distribution
rating_dist = df['rating_clean'].describe()

# Discount analysis
discount_bins = [0, 20, 40, 60, 80, 100]
discount_labels = ['0-20%', '20-40%', '40-60%', '60-80%', '80-100%']
df['discount_bucket'] = pd.cut(df['discount_percentage_clean'], bins=discount_bins, labels=discount_labels, include_lowest=True)
discount_analysis = df.groupby('discount_bucket').agg({
    'rating_clean': 'mean',
    'rating_count_clean': 'median',
    'product_id': 'count'
}).rename(columns={'product_id': 'count'})

# Top 10 products by rating_count
top_products = df.nlargest(10, 'rating_count_clean')[['product_name', 'rating_clean', 'rating_count_clean', 'top_category', 'discount_percentage_clean']]
top_products = top_products.head(10)

# Review sentiment
all_review_titles = []
for titles in df['review_title'].dropna():
    all_review_titles.extend([t.strip().lower() for t in str(titles).split(',')])

title_counts = Counter(all_review_titles)
positive_words = ['good', 'best', 'great', 'excellent', 'amazing', 'awesome', 'nice', 'value', 'perfect', 'super', 'love', 'quality', 'fast', 'recommend']
negative_words = ['bad', 'poor', 'worst', 'terrible', 'broken', 'defective', 'waste', 'disappointed', 'horrible', 'useless', 'damage', 'fake', 'slow', 'problem', 'issue', 'not']

positive_count = sum(title_counts.get(w, 0) for w in positive_words)
negative_count = sum(title_counts.get(w, 0) for w in negative_words)

# Price segment analysis
df['price_segment'] = pd.cut(df['discounted_price_clean'],
    bins=[0, 200, 500, 1000, 5000, 100000],
    labels=['Budget (₹0-200)', 'Economy (₹200-500)', 'Mid-range (₹500-1K)', 'Premium (₹1K-5K)', 'Luxury (₹5K+)']
)
price_segment_analysis = df.groupby('price_segment').agg({
    'rating_clean': 'mean',
    'discount_percentage_clean': 'mean',
    'rating_count_clean': 'median',
    'product_id': 'count'
}).rename(columns={'product_id': 'count'})

# Top categories data
top_cats = category_stats.head(8).copy()
bottom_cats = category_stats.tail(5).copy()

html_content = f'''<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Amazon Product Catalog Performance & Customer Sentiment Analysis</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        * {{
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }}
        body {{
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
            background: #f5f7fa;
            color: #1a1a2e;
            line-height: 1.6;
        }}
        .container {{
            max-width: 1400px;
            margin: 0 auto;
            padding: 20px;
        }}
        header {{
            background: linear-gradient(135deg, #232946 0%, #1a1a2e 100%);
            color: white;
            padding: 40px 20px;
            text-align: center;
        }}
        header h1 {{
            font-size: 2.2rem;
            font-weight: 600;
            margin-bottom: 10px;
        }}
        header p {{
            font-size: 1.1rem;
            opacity: 0.85;
        }}
        .section {{
            background: white;
            border-radius: 12px;
            padding: 30px;
            margin: 20px 0;
            box-shadow: 0 2px 12px rgba(0,0,0,0.06);
        }}
        .section-title {{
            font-size: 1.5rem;
            color: #1a1a2e;
            margin-bottom: 20px;
            padding-bottom: 10px;
            border-bottom: 3px solid #e94560;
            display: inline-block;
        }}
        .kpi-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 20px;
            margin: 20px 0;
        }}
        .kpi-card {{
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 25px;
            border-radius: 10px;
            text-align: center;
        }}
        .kpi-card.green {{ background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%); }}
        .kpi-card.orange {{ background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); }}
        .kpi-card.blue {{ background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); color: #1a1a2e; }}
        .kpi-value {{
            font-size: 2.5rem;
            font-weight: 700;
            margin: 10px 0;
        }}
        .kpi-label {{
            font-size: 0.9rem;
            opacity: 0.9;
            text-transform: uppercase;
            letter-spacing: 1px;
        }}
        .chart-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
            gap: 30px;
            margin: 20px 0;
        }}
        .chart-container {{
            background: #fafbfc;
            padding: 20px;
            border-radius: 10px;
            border: 1px solid #e8e8e8;
        }}
        .chart-title {{
            font-size: 1.1rem;
            font-weight: 600;
            color: #333;
            margin-bottom: 15px;
            text-align: center;
        }}
        .insight-box {{
            background: linear-gradient(135deg, #fff9c4 0%, #fff59d 100%);
            border-left: 4px solid #f57f17;
            padding: 15px 20px;
            margin: 15px 0;
            border-radius: 0 8px 8px 0;
        }}
        .insight-box.blue {{
            background: linear-gradient(135deg, #e3f2fd 0%, #bbdefb 100%);
            border-left-color: #1565c0;
        }}
        .insight-box.green {{
            background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%);
            border-left-color: #2e7d32;
        }}
        .insight-box.red {{
            background: linear-gradient(135deg, #ffebee 0%, #ffcdd2 100%);
            border-left-color: #c62828;
        }}
        .correlation-highlight {{
            display: flex;
            justify-content: center;
            align-items: center;
            gap: 40px;
            flex-wrap: wrap;
            padding: 20px;
            background: #f8f9fa;
            border-radius: 10px;
            margin: 20px 0;
        }}
        .correlation-item {{
            text-align: center;
            padding: 15px 25px;
            background: white;
            border-radius: 8px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.05);
        }}
        .correlation-value {{
            font-size: 2rem;
            font-weight: 700;
            color: #e94560;
        }}
        .correlation-value.positive {{ color: #11998e; }}
        .correlation-value.weak {{ color: #f39c12; }}
        .correlation-label {{
            font-size: 0.85rem;
            color: #666;
            margin-top: 5px;
        }}
        table {{
            width: 100%;
            border-collapse: collapse;
            margin: 15px 0;
        }}
        th, td {{
            padding: 12px 15px;
            text-align: left;
            border-bottom: 1px solid #e0e0e0;
        }}
        th {{
            background: #f8f9fa;
            font-weight: 600;
            color: #333;
        }}
        tr:hover {{
            background: #f5f5f5;
        }}
        .category-badge {{
            display: inline-block;
            padding: 4px 10px;
            border-radius: 20px;
            font-size: 0.8rem;
            font-weight: 500;
        }}
        .category-badge.high {{ background: #c8e6c9; color: #2e7d32; }}
        .category-badge.medium {{ background: #fff9c4; color: #f57f17; }}
        .category-badge.low {{ background: #ffcdd2; color: #c62828; }}
        .recommendations {{
            display: grid;
            gap: 20px;
        }}
        .recommendation {{
            background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
            padding: 20px 25px;
            border-radius: 10px;
            border-left: 5px solid #667eea;
        }}
        .recommendation h4 {{
            color: #1a1a2e;
            margin-bottom: 10px;
            font-size: 1.1rem;
        }}
        .recommendation p {{
            color: #555;
            font-size: 0.95rem;
        }}
        .metric {{
            font-weight: 600;
            color: #e94560;
        }}
        .footer {{
            text-align: center;
            padding: 30px;
            color: #666;
            font-size: 0.9rem;
        }}
        @media (max-width: 768px) {{
            .chart-grid {{ grid-template-columns: 1fr; }}
            header h1 {{ font-size: 1.5rem; }}
        }}
    </style>
</head>
<body>
    <header>
        <h1>Amazon Product Catalog Performance & Customer Sentiment Analysis</h1>
        <p>Comprehensive analysis of {total_products:,} products | Data-driven insights for category and pricing strategy</p>
    </header>

    <div class="container">
        <!-- Executive Overview -->
        <section class="section">
            <h2 class="section-title">Executive Overview</h2>

            <div class="kpi-grid">
                <div class="kpi-card">
                    <div class="kpi-label">Total Products Analyzed</div>
                    <div class="kpi-value">{total_products:,}</div>
                </div>
                <div class="kpi-card green">
                    <div class="kpi-label">Average Product Rating</div>
                    <div class="kpi-value">{avg_rating:.2f} <span style="font-size:1rem;">★</span></div>
                </div>
                <div class="kpi-card orange">
                    <div class="kpi-label">Median Discount</div>
                    <div class="kpi-value">{median_discount:.0f}%</div>
                </div>
                <div class="kpi-card blue">
                    <div class="kpi-label">High-Rating Share (≥4.0★)</div>
                    <div class="kpi-value">{high_rating_share:.1f}%</div>
                </div>
            </div>

            <div class="insight-box blue">
                <strong>Key Insight:</strong> The catalog maintains a healthy average rating of <strong>{avg_rating:.2f}★</strong> with
                <strong>{high_rating_share:.1f}%</strong> of products rated 4.0 or above. The median discount of <strong>{median_discount:.0f}%</strong>
                indicates aggressive promotional pricing across the catalog.
            </div>

            <div class="chart-grid">
                <div class="chart-container">
                    <div class="chart-title">Rating Distribution</div>
                    <canvas id="ratingDistChart"></canvas>
                </div>
                <div class="chart-container">
                    <div class="chart-title">Discount Percentage Distribution</div>
                    <canvas id="discountDistChart"></canvas>
                </div>
            </div>
        </section>

        <!-- Category Performance -->
        <section class="section">
            <h2 class="section-title">Category Performance Breakdown</h2>

            <div class="insight-box">
                <strong>Dataset Scope:</strong> {len(category_stats)} top-level categories analyzed across the entire catalog.
                Electronics dominates with the majority of products.
            </div>

            <div class="chart-grid">
                <div class="chart-container">
                    <div class="chart-title">Average Rating by Category</div>
                    <canvas id="categoryRatingChart"></canvas>
                </div>
                <div class="chart-container">
                    <div class="chart-title">Average Discount by Category</div>
                    <canvas id="categoryDiscountChart"></canvas>
                </div>
            </div>

            <h3 style="margin: 25px 0 15px; color: #333;">Top 5 Categories by Rating</h3>
            <table>
                <thead>
                    <tr>
                        <th>Category</th>
                        <th>Products</th>
                        <th>Avg Rating</th>
                        <th>Avg Discount</th>
                        <th>Median Rating Count</th>
                    </tr>
                </thead>
                <tbody>
'''

for idx, (cat, row) in enumerate(top_cats.iterrows()):
    rating_class = 'high' if row['avg_rating'] >= 4.0 else 'medium' if row['avg_rating'] >= 3.5 else 'low'
    html_content += f'''                    <tr>
                        <td><span class="category-badge {rating_class}">{cat}</span></td>
                        <td>{int(row['count'])}</td>
                        <td><strong>{row['avg_rating']:.2f} ★</strong></td>
                        <td>{row['avg_discount']:.1f}%</td>
                        <td>{int(row['median_rating_count']) if pd.notna(row['median_rating_count']) else 'N/A'}</td>
                    </tr>
'''

html_content += f'''                </tbody>
            </table>

            <h3 style="margin: 25px 0 15px; color: #333;">Bottom 5 Categories by Rating</h3>
            <table>
                <thead>
                    <tr>
                        <th>Category</th>
                        <th>Products</th>
                        <th>Avg Rating</th>
                        <th>Avg Discount</th>
                        <th>Median Rating Count</th>
                    </tr>
                </thead>
                <tbody>
'''

for idx, (cat, row) in enumerate(bottom_cats.iterrows()):
    rating_class = 'high' if row['avg_rating'] >= 4.0 else 'medium' if row['avg_rating'] >= 3.5 else 'low'
    html_content += f'''                    <tr>
                        <td><span class="category-badge {rating_class}">{cat}</span></td>
                        <td>{int(row['count'])}</td>
                        <td><strong>{row['avg_rating']:.2f} ★</strong></td>
                        <td>{row['avg_discount']:.1f}%</td>
                        <td>{int(row['median_rating_count']) if pd.notna(row['median_rating_count']) else 'N/A'}</td>
                    </tr>
'''

html_content += f'''                </tbody>
            </table>
        </section>

        <!-- Pricing & Discount Strategy -->
        <section class="section">
            <h2 class="section-title">Pricing & Discount Strategy Analysis</h2>

            <div class="correlation-highlight">
                <div class="correlation-item">
                    <div class="correlation-value weak">{correlation_discount_rating:.3f}</div>
                    <div class="correlation-label">Correlation: Discount % vs Rating</div>
                </div>
                <div class="correlation-item">
                    <div class="correlation-value positive">{correlation_discount_count:.3f}</div>
                    <div class="correlation-label">Correlation: Discount % vs Review Volume</div>
                </div>
            </div>

            <div class="insight-box red">
                <strong>Key Finding:</strong> There is a <strong>weak negative correlation ({correlation_discount_rating:.3f})</strong>
                between discount depth and customer rating. This suggests that <strong>deeper discounts do NOT translate to higher satisfaction</strong>.
                Products with higher discounts tend to have slightly lower ratings on average.
            </div>

            <div class="insight-box green">
                <strong>Volume Effect:</strong> The near-zero correlation ({correlation_discount_count:.3f}) between discount and review count
                indicates that discounts have minimal impact on driving engagement volume.
            </div>

            <div class="chart-grid">
                <div class="chart-container">
                    <div class="chart-title">Discount vs Rating Scatter</div>
                    <canvas id="scatterChart"></canvas>
                </div>
                <div class="chart-container">
                    <div class="chart-title">Average Rating by Discount Range</div>
                    <canvas id="discountRatingChart"></canvas>
                </div>
            </div>

            <h3 style="margin: 25px 0 15px; color: #333;">Rating by Discount Range</h3>
            <table>
                <thead>
                    <tr>
                        <th>Discount Range</th>
                        <th>Products</th>
                        <th>Avg Rating</th>
                        <th>Median Rating Count</th>
                    </tr>
                </thead>
                <tbody>
'''

for bucket, row in discount_analysis.iterrows():
    html_content += f'''                    <tr>
                        <td><strong>{bucket}</strong></td>
                        <td>{int(row['count'])}</td>
                        <td>{row['rating_clean']:.2f} ★</td>
                        <td>{int(row['rating_count_clean']) if pd.notna(row['rating_count_clean']) else 'N/A'}</td>
                    </tr>
'''

html_content += f'''                </tbody>
            </table>

            <h3 style="margin: 25px 0 15px; color: #333;">Performance by Price Segment</h3>
            <table>
                <thead>
                    <tr>
