import pandas as pd
import numpy as np
import json
import base64
from io import BytesIO
from collections import Counter

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# Clean price columns
def clean_price(x):
    if pd.isna(x):
        return np.nan
    x = str(x).replace('₹', '').replace(',', '').strip()
    try:
        return float(x)
    except:
        return np.nan

def clean_discount(x):
    if pd.isna(x):
        return np.nan
    x = str(x).replace('%', '').strip()
    try:
        return float(x)
    except:
        return np.nan

def clean_rating_count(x):
    if pd.isna(x):
        return np.nan
    x = str(x).replace(',', '').strip()
    try:
        return int(float(x))
    except:
        return np.nan

def clean_rating(x):
    if pd.isna(x):
        return np.nan
    try:
        return float(x)
    except:
        return np.nan

df['discounted_price_clean'] = df['discounted_price'].apply(clean_price)
df['actual_price_clean'] = df['actual_price'].apply(clean_price)
df['discount_percentage_clean'] = df['discount_percentage'].apply(clean_discount)
df['rating_clean'] = df['rating'].apply(clean_rating)
df['rating_count_clean'] = df['rating_count'].apply(clean_rating_count)

# Extract categories
def get_top_category(x):
    if pd.isna(x):
        return 'Unknown'
    parts = str(x).split('|')
    return parts[0].strip() if parts else 'Unknown'

df['top_category'] = df['category'].apply(get_top_category)

# Calculate correlations
valid_data = df.dropna(subset=['discount_percentage_clean', 'rating_clean'])
correlation_discount_rating = valid_data['discount_percentage_clean'].corr(valid_data['rating_clean'])

valid_data_rc = df.dropna(subset=['discount_percentage_clean', 'rating_count_clean'])
correlation_discount_count = valid_data_rc['discount_percentage_clean'].corr(valid_data_rc['rating_count_clean'])

# KPIs
total_products = len(df)
avg_rating = df['rating_clean'].mean()
median_discount = df['discount_percentage_clean'].median()
median_rating_count = df['rating_count_clean'].median()
high_rating_share = (df['rating_clean'] >= 4.0).sum() / total_products * 100

# Category stats
category_stats = df.groupby('top_category').agg({
    'product_id': 'count',
    'rating_clean': 'mean',
    'discount_percentage_clean': 'mean',
    'rating_count_clean': 'median'
}).rename(columns={
    'product_id': 'count',
    'rating_clean': 'avg_rating',
    'discount_percentage_clean': 'avg_discount',
    'rating_count_clean': 'median_rating_count'
}).sort_values('avg_rating', ascending=False)

# Rating distribution
rating_dist = df['rating_clean'].describe()

# Discount analysis
discount_bins = [0, 20, 40, 60, 80, 100]
discount_labels = ['0-20%', '20-40%', '40-60%', '60-80%', '80-100%']
df['discount_bucket'] = pd.cut(df['discount_percentage_clean'], bins=discount_bins, labels=discount_labels, include_lowest=True)
discount_analysis = df.groupby('discount_bucket').agg({
    'rating_clean': 'mean',
    'rating_count_clean': 'median',
    'product_id': 'count'
}).rename(columns={'product_id': 'count'})

# Top 10 products by rating_count
top_products = df.nlargest(10, 'rating_count_clean')[['product_name', 'rating_clean', 'rating_count_clean', 'top_category', 'discount_percentage_clean']]
top_products = top_products.head(10)

# Review sentiment
all_review_titles = []
for titles in df['review_title'].dropna():
    all_review_titles.extend([t.strip().lower() for t in str(titles).split(',')])

title_counts = Counter(all_review_titles)
positive_words = ['good', 'best', 'great', 'excellent', 'amazing', 'awesome', 'nice', 'value', 'perfect', 'super', 'love', 'quality', 'fast', 'recommend']
negative_words = ['bad', 'poor', 'worst', 'terrible', 'broken', 'defective', 'waste', 'disappointed', 'horrible', 'useless', 'damage', 'fake', 'slow', 'problem', 'issue', 'not']

positive_count = sum(title_counts.get(w, 0) for w in positive_words)
negative_count = sum(title_counts.get(w, 0) for w in negative_words)

# Price segment analysis
df['price_segment'] = pd.cut(df['discounted_price_clean'],
    bins=[0, 200, 500, 1000, 5000, 100000],
    labels=['Budget (₹0-200)', 'Economy (₹200-500)', 'Mid-range (₹500-1K)', 'Premium (₹1K-5K)', 'Luxury (₹5K+)']
)
price_segment_analysis = df.groupby('price_segment').agg({
